/* @autogenerated */
package net.civeira.phylax.common.infrastructure.consistency;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Function;
import java.util.function.Predicate;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;

import io.quarkus.cache.Cache;
import io.quarkus.cache.runtime.noop.NoOpCache;
import io.smallrye.mutiny.Uni;
import jakarta.transaction.Status;
import jakarta.transaction.Synchronization;
import jakarta.transaction.TransactionSynchronizationRegistry;

class PendingWritesRegistryUnitTest {
  private static final Duration WINDOW = Duration.ofSeconds(60);

  private TransactionSynchronizationRegistry transactions;
  private MutableClock clock;
  private FakeCache cache;

  @BeforeEach
  void setUp() {
    transactions = mock(TransactionSynchronizationRegistry.class);
    Map<Object, Object> resources = new HashMap<>();
    when(transactions.getResource(any())).thenAnswer(inv -> resources.get(inv.getArgument(0)));
    doAnswer(inv -> resources.put(inv.getArgument(0), inv.getArgument(1))).when(transactions)
        .putResource(any(), any());
    when(transactions.getTransactionStatus()).thenReturn(Status.STATUS_NO_TRANSACTION);
    clock = new MutableClock(Instant.parse("2026-10-13T10:00:00Z"));
    cache = new FakeCache();
  }

  @Test
  void testNotPendingWithoutWrites() {
    assertFalse(withCache().isPending("role"));
    assertFalse(withCacheDisabled().isPending("role"));
  }

  @Test
  void testPendingInsideTheWindowWithCache() {
    PendingWritesRegistry registry = withCache();
    assertFalse(registry.isPending("role"));

    registry.mark("role");

    assertTrue(registry.isPending("role"));
    assertFalse(registry.isPending("user"));
    clock.advance(Duration.ofSeconds(61));
    assertFalse(registry.isPending("role"));
  }

  @Test
  void testMarkIsStoredWhenAReaderLoadsTheKeyInBetween() {
    PendingWritesRegistry registry = withCache();
    cache.beforeNextLoad = () -> registry.isPending("role");

    registry.mark("role");

    assertTrue(registry.isPending("role"));
  }

  @Test
  void testPendingInsideTheWindowWithCacheDisabled() {
    PendingWritesRegistry registry = withCacheDisabled();

    registry.mark("role");

    assertTrue(registry.isPending("role"));
    assertFalse(registry.isPending("user"));
    clock.advance(Duration.ofSeconds(61));
    assertFalse(registry.isPending("role"));
  }

  @Test
  void testPurgeRemovesOnlyExpiredLocalMarks() {
    PendingWritesRegistry registry = withCacheDisabled();
    registry.mark("role");
    clock.advance(Duration.ofSeconds(30));
    registry.mark("user");
    clock.advance(Duration.ofSeconds(40));

    registry.purge();

    assertFalse(registry.isPending("role"));
    assertTrue(registry.isPending("user"));
  }

  @Test
  void testNoSynchronizationWithoutTransaction() {
    withCache().mark("role");

    verify(transactions, never()).registerInterposedSynchronization(any());
  }

  @Test
  void testRegisterOnlyOneSynchronizationPerEntityAndTransaction() {
    when(transactions.getTransactionStatus()).thenReturn(Status.STATUS_ACTIVE);
    PendingWritesRegistry registry = withCache();

    registry.mark("role");
    registry.mark("role");
    registry.mark("user");

    verify(transactions, times(2)).registerInterposedSynchronization(any());
  }

  @Test
  void testRenewTheWindowAfterCommit() {
    PendingWritesRegistry registry = withCache();
    Synchronization sync = markInsideTransaction(registry);

    clock.advance(Duration.ofSeconds(50));
    sync.afterCompletion(Status.STATUS_COMMITTED);
    clock.advance(Duration.ofSeconds(50));

    assertTrue(registry.isPending("role"));
  }

  @Test
  void testKeepTheWindowAfterRollback() {
    PendingWritesRegistry registry = withCacheDisabled();
    Synchronization sync = markInsideTransaction(registry);

    clock.advance(Duration.ofSeconds(50));
    sync.afterCompletion(Status.STATUS_ROLLEDBACK);
    clock.advance(Duration.ofSeconds(50));

    assertFalse(registry.isPending("role"));
  }

  private Synchronization markInsideTransaction(PendingWritesRegistry registry) {
    when(transactions.getTransactionStatus()).thenReturn(Status.STATUS_ACTIVE);
    registry.mark("role");
    ArgumentCaptor<Synchronization> sync = ArgumentCaptor.forClass(Synchronization.class);
    verify(transactions).registerInterposedSynchronization(sync.capture());
    return sync.getValue();
  }

  private PendingWritesRegistry withCache() {
    return new PendingWritesRegistry(cache, transactions, WINDOW, clock);
  }

  private PendingWritesRegistry withCacheDisabled() {
    return new PendingWritesRegistry(new NoOpCache(), transactions, WINDOW, clock);
  }

  /**
   * Behaves like the Quarkus cache: get only runs the loader when the key is absent.
   */
  private static class FakeCache implements Cache {
    private final Map<Object, Object> values = new ConcurrentHashMap<>();
    private Runnable beforeNextLoad;

    @Override
    public String getName() {
      return "pending-writes";
    }

    @Override
    public Object getDefaultKey() {
      return "default";
    }

    @Override
    @SuppressWarnings("unchecked")
    public <K, V> Uni<V> get(K key, Function<K, V> valueLoader) {
      Runnable hook = beforeNextLoad;
      if (null != hook && !values.containsKey(key)) {
        beforeNextLoad = null;
        hook.run();
      }
      return Uni.createFrom().item((V) values.computeIfAbsent(key, k -> valueLoader.apply((K) k)));
    }

    @Override
    public <K, V> Uni<V> getAsync(K key, Function<K, Uni<V>> valueLoader) {
      throw new UnsupportedOperationException();
    }

    @Override
    public Uni<Void> invalidate(Object key) {
      values.remove(key);
      return Uni.createFrom().voidItem();
    }

    @Override
    public Uni<Void> invalidateAll() {
      values.clear();
      return Uni.createFrom().voidItem();
    }

    @Override
    public Uni<Void> invalidateIf(Predicate<Object> predicate) {
      values.keySet().removeIf(predicate);
      return Uni.createFrom().voidItem();
    }

    @Override
    public <T extends Cache> T as(Class<T> type) {
      throw new IllegalStateException("Not a " + type);
    }
  }

  private static class MutableClock extends Clock {
    private Instant now;

    MutableClock(Instant now) {
      this.now = now;
    }

    void advance(Duration duration) {
      now = now.plus(duration);
    }

    @Override
    public ZoneId getZone() {
      return ZoneOffset.UTC;
    }

    @Override
    public Clock withZone(ZoneId zone) {
      return this;
    }

    @Override
    public Instant instant() {
      return now;
    }
  }
}
